mapper.update:
UPDATE user_access_review uar SET final_review_time = CURRENT_TIMESTAMP, final_review_decision = 'remove', final_review_result_reason = 'User ITCode is invalid' WHERE uar.final_review_decision IS NULL AND uar.cmdb_id IN (
#{item}
) AND COALESCE(uar.line_manager_band_ed_flag, '') != '1' AND NOT EXISTS ( SELECT 1 FROM ad_tb_upp_nature_2 lm WHERE lm.user_name = uar.line_manager and lm.band_flag = '1' ) AND NOT EXISTS ( SELECT 1 FROM ad_tb_upp_nature_2 upp WHERE upp.user_name = uar.it_code_of_user );

UPDATE user_access_review uar SET line_manager_review_status = CASE WHEN COALESCE(uar.line_manager_review_status, '') != '2' THEN '2' ELSE uar.line_manager_review_status END, line_managers_review_decision = CASE WHEN COALESCE(uar.line_manager_review_status, '') != '2' THEN '/' ELSE uar.line_managers_review_decision END, line_manager_review_time = CASE WHEN COALESCE(uar.line_manager_review_status, '') != '2' THEN CURRENT_TIMESTAMP ELSE uar.line_manager_review_time END, final_review_time = CASE WHEN COALESCE(uar.line_manager_review_status, '') != '2' THEN null ELSE uar.final_review_time END, final_review_decision = CASE WHEN uar.bpo_review_decision = 'remove' THEN 'remove' ELSE '/' END, final_review_result_reason = CASE WHEN uar.bpo_review_decision = 'remove' THEN 'BPO''s review result is "Remove"' ELSE 'Line managers who are SVP or above are not included in this review cycle. Their review results will be consolidated and processed together after the annual review is completed.' END WHERE uar.final_review_decision IS NULL AND ( COALESCE(uar.line_manager_band_ed_flag, '') = '1' OR EXISTS ( SELECT 1 FROM ad_tb_upp_nature_2 lm WHERE lm.user_name = uar.line_manager and lm.band_flag = '1' ) ) AND uar.cmdb_id IN (
#{item}
)

UPDATE user_access_review uar SET final_review_time = CURRENT_TIMESTAMP, final_review_decision = CASE -- 双方都保留 WHEN line_managers_review_decision = 'keep' AND bpo_review_decision = 'keep' THEN 'keep' -- 其余全部为移除 ELSE 'remove' END, final_review_result_reason = CASE -- 双方都保留 WHEN line_managers_review_decision = 'keep' AND bpo_review_decision = 'keep' THEN 'Both Line Manager and BPO review results are "Keep"' -- 双方都移除 WHEN line_managers_review_decision = 'remove' AND bpo_review_decision = 'remove' THEN 'Both Line Manager and BPO review results are "Remove"' -- LM 移除（BPO 任意非移除） WHEN line_managers_review_decision = 'remove' THEN 'Line Manager''s review result is "Remove"' -- BPO 移除（LM 非移除） WHEN bpo_review_decision = 'remove' THEN 'BPO''s review result is "Remove"' -- 双方都未回复 WHEN line_manager_review_status = '1' AND bpo_review_status = '1' THEN 'Neither Line Manager nor BPO responded' -- BPO 未回复（LM 任意回复） WHEN bpo_review_status = '1' THEN 'BPO did not respond' -- LM 未回复（BPO 任意回复） WHEN line_manager_review_status = '1' THEN 'Line Manager did not respond' ELSE 'Unknown Reason' END WHERE uar.final_review_decision is null AND NOT EXISTS ( SELECT 1 FROM ad_tb_upp_nature_2 lm WHERE lm.user_name = uar.line_manager and lm.band_flag = '1' ) AND uar.cmdb_id in (
#{item}
)

