insert into allow_send_email_include_final_remove_user (it_code_of_user,it_code_of_user_email,send_flag,ccs_line_manager,level) ( SELECT LOWER(TRIM(a.user_name)) AS it_code_lower, a.email ,0 as send_flag , case when b.band_flag ='1' then null else b.email end as lm_email, b.band_flag AS level FROM ad_tb_upp_nature_2 a left join ad_tb_upp_nature_2 b on a.manager1st = b.user_name WHERE a.user_name IN
#{itcode}
);

mapper.select:
SELECT
    lower(ur.line_manager) AS line_manager,
    COALESCE(string_agg(DISTINCT a.email, ',') FILTER (WHERE a.email IS NOT NULL AND trim(a.email) <> '' AND lower(trim(a.email)) <> 'null'),'') AS email
FROM ad_tb_upp_nature_2 a
JOIN user_access_review ur ON lower(a.user_name) = lower(ur.it_code_of_user)
JOIN its_application_data iad on ur.cmdb_id = iad.cmdb_id
WHERE 1=1
    AND ur.line_manager_review_status != '2'
    AND ur.overall_send_status = 'Pending'

        AND ur.it_code_of_user = #{bean.itCodeOfUser}


        AND ur.line_manager = #{bean.lineManager}


        AND ur.line_manager_level_code = #{bean.lineManagerLevelCode}


        AND ur.dept like '%'||#{bean.dept}||'%'


        AND ur.line_manager_review_status = #{bean.lineManagerReviewStatus}


        AND ur.bpo = #{bean.bpo}


        AND ur.bpo_review_status = #{bean.bpoReviewStatus}


        AND ur.cmdb_id IN

            #{type}



        AND iad.application_name IN

            #{type}


    AND lower(ur.line_manager) IN

        #{item.lineManager}

GROUP BY ur.line_manager

